makeMtLab(document.getElementById("lab-l7"),{id:"l7",scenarios:[{"label": "Ví dụ: Tìm nút cổ chai", "note": "Máy có chu kỳ dài nhất giới hạn cả dây chuyền.", "steps": [{"t": "Chu kỳ ba máy", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Trạm<\/th><th scope=\"col\">Chu kỳ<\/th><\/tr><\/thead><tbody><tr><td>M1<\/td><td>2,0 s<\/td><\/tr><tr><td>M2<\/td><td>1,8 s<\/td><\/tr><tr><td>M3<\/td><td>1,5 s<\/td><\/tr><\/tbody><\/table>"}, {"t": "Nút cổ chai là M1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Trạm<\/th><th scope=\"col\">Chu kỳ<\/th><\/tr><\/thead><tbody><tr><td class=\"hi\">M1<\/td><td class=\"hi\">2,0 s<\/td><\/tr><tr><td>M2<\/td><td>1,8 s<\/td><\/tr><tr><td>M3<\/td><td>1,5 s<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Máy nào là nút cổ chai?", "o": ["M1", "M2", "M3"], "a": 0}}, {"t": "Năng lực dây chuyền", "html": "<p class=\"mt-calc\">3 600 s / 2,0 s = 1 800 hộp/giờ<\/p>"}]}, {"label": "Ví dụ: Thời gian chạy lệnh 6 000 hộp", "note": "Chuyển đổi cộng số lượng nhân chu kỳ nút cổ chai.", "steps": [{"t": "Thời gian sản xuất", "html": "<p class=\"mt-calc\">6 000 × 2,0 s = 12 000 s = 200 phút<\/p>"}, {"t": "Cộng chuyển đổi", "html": "<p class=\"mt-calc\">200 + 15 = <b>215 phút<\/b><\/p>", "ask": {"q": "Tổng thời gian chạy lệnh là bao nhiêu phút?", "o": ["200", "215", "530"], "a": 1}}]}, {"label": "Ví dụ: Thay M1 bằng máy nhanh hơn", "note": "Nút cổ chai dịch sang máy khác.", "steps": [{"t": "M1 mới: 1,6 s", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Trạm<\/th><th scope=\"col\">Chu kỳ<\/th><\/tr><\/thead><tbody><tr><td>M1<\/td><td>1,6 s<\/td><\/tr><tr><td>M2<\/td><td class=\"hi\">1,8 s<\/td><\/tr><tr><td>M3<\/td><td>1,5 s<\/td><\/tr><\/tbody><\/table>"}, {"t": "Nút cổ chai mới là M2", "html": "<p class=\"mt-calc\">3 600 / 1,8 = <b>2 000 hộp/giờ<\/b><\/p>", "say": "<p>Năng lực chỉ tăng tới mức của máy chậm thứ hai.<\/p>", "ask": {"q": "Năng lực mới là bao nhiêu hộp/giờ?", "o": ["2 250", "2 000", "1 800"], "a": 1}}]}, {"label": "Bẫy: Cộng chu kỳ các máy", "note": "Ba máy làm việc song song trên ba hộp khác nhau.", "steps": [{"t": "Cộng 2,0 + 1,8 + 1,5", "html": "<p class=\"mt-calc\">5,3 s/hộp → 3 600 / 5,3 ≈ 679 hộp/giờ<\/p>", "ask": {"q": "Con số 679 hộp/giờ đúng không?", "o": ["Đúng", "Sai: phải dùng nút cổ chai"], "a": 1}}, {"t": "Sửa: dùng chu kỳ nút cổ chai", "html": "<p class=\"mt-calc\">3 600 / 2,0 = 1 800 hộp/giờ<\/p>", "say": "<p>5,3 s là thời gian một hộp đi qua cả ba máy (thời gian xuyên suốt), không phải nhịp ra hộp.<\/p>"}]}, {"label": "Lỗi: Không kiểm tra bỏ bước", "note": "Hộp chưa dán nắp vẫn được ghi đạt.", "steps": [{"t": "Hộp 08812 qua M1 rồi tới M3", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Công đoạn<\/th><th scope=\"col\">Đã qua?<\/th><\/tr><\/thead><tbody><tr><td>10 Rót<\/td><td>Có<\/td><\/tr><tr><td>20 Dán nắp<\/td><td class=\"bad\">Không<\/td><\/tr><tr><td>30 Cân<\/td><td>Đang cân<\/td><\/tr><\/tbody><\/table>"}, {"t": "Sửa: M3 kiểm tra công đoạn trước", "html": "<p class=\"mt-calc\">Nếu công đoạn 20 chưa hoàn tất → MES báo lỗi, không ghi đạt<\/p>", "say": "<p>Đây là chức năng quản lý quy trình của MESA.<\/p>"}]}]});
